<?php require 'includes/db.php';session_start();$err='';if($_SERVER['REQUEST_METHOD']==='POST'){$e=trim($_POST['email']??'');$p=$_POST['password']??'';$q=$pdo->prepare('SELECT * FROM students WHERE email=?');$q->execute([$e]);$u=$q->fetch();if($u&&password_verify($p,$u['password'])){$_SESSION['student_id']=$u['id'];$_SESSION['student_name']=$u['name'];header('Location: index.php');exit;}else{$err='Invalid email or password.';}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Student Login | ScholarConnect Pro</title><link rel="stylesheet" href="css/style.css"></head><body><?php include 'includes/header.php';?><section class="auth-wrap"><div class="auth-card"><span class="eyebrow">STUDENT ACCESS</span><h1>Student Login</h1><?php if(isset($_GET['registered'])):?><div class="success">Registration successful. Please log in.</div><?php endif;?><?php if(isset($_GET['login_required'])):?><div class="notice">Please log in to use your student dashboard and save scholarships.</div><?php endif;?><?php if($err):?><div class="notice"><?=htmlspecialchars($err)?></div><?php endif;?><form method="post"><label>Email<input name="email" type="email" required></label><label>Password<input name="password" type="password" required></label><button class="btn btn-primary">Login</button></form><p class="form-link">New student? <a href="register.php">Create an account</a></p></div></section><?php include 'includes/footer.php';?></body></html>
